declare const codj: CoDj;

/** Hooks a co-DJ script may export (all optional). Writes made inside onBar land on the NEXT bar. */
declare function setup(codj: CoDj, ctx: HookCtx): void;
declare function onBar(codj: CoDj, ctx: HookCtx & { bar: number }): void;
declare function onBeat(codj: CoDj, ctx: HookCtx & { beat: number }): void;
declare function onEvent(codj: CoDj, ctx: HookCtx & { event: CoDjEvent }): void;
declare function onMessage(codj: CoDj, ctx: HookCtx & { message: ChatMessage }): void;
